import {mkdir,readFile,writeFile,cp,readdir,lstat,readlink,realpath} from 'node:fs/promises';
import {join,dirname,relative} from 'node:path';
import {spawnSync} from 'node:child_process';
import assert from 'node:assert/strict';
const root=process.argv[1], scratch=process.argv[2], home=join(scratch,'valid-home');
await mkdir(home,{recursive:true});
const env={PATH:process.env.PATH,HOME:home,TMPDIR:scratch};
const run=(args,cwd=root)=>{const r=spawnSync(process.execPath,args,{cwd,env,encoding:'utf8',timeout:20000});return {exit:r.status,stdout:r.stdout,stderr:r.stderr};};
const snapshot=async(root)=>{const out={};const walk=async(p)=>{const s=await lstat(p,{bigint:true});out[relative(root,p)]={ino:String(s.ino),mode:String(s.mode),mtime:String(s.mtimeNs),ctime:String(s.ctimeNs),value:s.isSymbolicLink()?await readlink(p):s.isFile()?(await readFile(p)).toString('base64'):null};if(s.isDirectory())for(const n of(await readdir(p)).sort())await walk(join(p,n));};await walk(root);return JSON.stringify(out);};
const results={};
results.install=run(['kit/bin/jev.mjs','install','cli','--apply','--dir',home,'--robot']);assert.equal(results.install.exit,0);
const bin=join(home,'.local/bin/classifier');const pkg=JSON.parse(await readFile(join(root,'kit/package.json'),'utf8'));
results.version=run([bin,'--version']);assert.equal(results.version.stdout,`classifier ${pkg.version}\n`);
const versionRoot=dirname(dirname(await realpath(bin)));
results.sdk=run(['--input-type=module','--eval',"await import('@typesafe-ai/sdk'); console.log('SDK_ENTRY_LOADED');"],versionRoot);assert.equal(results.sdk.exit,0);assert.equal(results.sdk.stdout,'SDK_ENTRY_LOADED\n');
results.doctor=run([bin,'doctor','--robot']);assert.equal(results.doctor.exit,1);assert.ok(results.doctor.stdout.includes('FINDINGS'));assert.ok(results.doctor.stdout.includes('NOT_RUN'));JSON.parse(results.doctor.stdout);
results.runner=run([join(versionRoot,'runners/jev-latest-canary-run.sh'),'--help']);
const runner=spawnSync('/bin/bash',[join(versionRoot,'runners/jev-latest-canary-run.sh'),'--help'],{env,cwd:home,encoding:'utf8',timeout:10000});results.runner={exit:runner.status,stdout:runner.stdout,stderr:runner.stderr};assert.equal(results.runner.exit,0);
const before=await snapshot(home);results.repeat=run(['kit/bin/jev.mjs','install','cli','--apply','--dir',home,'--robot']);assert.equal(results.repeat.exit,0);assert.equal(JSON.parse(results.repeat.stdout).data.status,'already');assert.equal(await snapshot(home),before);
const {installCli}=await import(join(root,'kit/dist/install/cli-target.js'));
for(const [label,omit,reserved] of [['missing-sdk','node_modules/@typesafe-ai/sdk/dist/index.mjs',false],['reserved-manifest',null,true]]){
 const source=join(scratch,label+'-source'),target=join(scratch,label+'-home');await mkdir(source);await mkdir(target);
 for(const p of [...pkg.files,'package.json','node_modules/@typesafe-ai/sdk']){const dest=join(source,p);await mkdir(dirname(dest),{recursive:true});await cp(join(root,'kit',p),dest,{recursive:true,filter:p=>relative(join(root,'kit'),p)!==omit});}
 if(reserved){await writeFile(join(source,'.classifier-install.json'),JSON.stringify({version:2,entries:[]}));await writeFile(join(source,'package.json'),JSON.stringify({...pkg,files:[...pkg.files,'.classifier-install.json']}));}
 const original=await snapshot(target);let error;try{await installCli({home:target,version:pkg.version,packageDir:source});}catch(e){error={code:e.code,message:e.message};}assert.equal(error?.code,'USAGE');assert.equal(await snapshot(target),original);results[label]={error,wholeHomeUnchanged:true};
}
console.log(JSON.stringify({results,validWholeHomeRepeatUnchanged:true},null,2));
